ValidationRule.errorConditionFormula:
AND(

    NOT($Setup.Metadata_Activation_Settings__c.Disable_VR__c && OR(ISBLANK($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c),
    CONTAINS($Setup.Metadata_Activation_Settings__c.SObject_API_Name__c, 'Opportunity'))),

      /*--Block Stage 5 -> 6 when Booking Verification is Rejected or Blank or Hold-Pending Correction--*/

     ISPICKVAL(StageName, '6 - Setup'), 
     ISPICKVAL(PRIORVALUE(StageName), '5 - Signed/PO in'),
     OR(
         /*--US and Canada with TAA >= 25k--*/
         AND(
            OR(
              ( Billing_Country__r.Name ) = 'United States',
              ( Billing_Country__r.Name ) = 'Canada'
            ),
            (Amount / CURRENCYRATE(TEXT(CurrencyIsoCode))) >= 25000
          ),
          OR(
             /*--Mexico, Brazil, Peru, Spain & No TAA condition--*/
             ( Billing_Country__r.Name ) = 'Mexico',
             ( Billing_Country__r.Name ) = 'Brazil',
             ( Billing_Country__r.Name ) = 'Peru',
             ( Billing_Country__r.Name ) = 'Spain'
           )          
         ),
     OR(
          ISPICKVAL( Deal_Validation__c , 'Reject'),
          ISPICKVAL( Deal_Validation__c , ''),
          ISPICKVAL( Deal_Validation__c , 'Hold-Pending Correction')
       ),
     /* BV flag is by default False mainly use to validate Existing Opp which are already at Stage 5*/
       Booking_Verification_Validation__c = false,

      /*--Limit to allowed Record Types--*/
 OR(
   ( RecordType.DeveloperName ) = 'Standard_Opportunity',
   ( RecordType.DeveloperName ) = 'IMLA_Standard_Opportunity',
   ( RecordType.DeveloperName ) = 'IMAP_Standard_Opportunity',
   ( RecordType.DeveloperName ) = 'IME_Standard_Opportunity'
 ),
 /*--Bypass Admins from this VR--*/
 $Profile.Name <> 'System Administrator',
 $Profile.Name <> 'IM_Custom Sys Admin',
 NOT($Permission.VR_Bypass_Permission)

)
